python3 -c "
import json

# Load all definitions
with open('/tmp/ixp_node_def.json') as f: ixp_def = json.load(f)
with open('/tmp/end_node_def.json') as f: end_def = json.load(f)
with open('/tmp/script_node_def.json') as f: script_def = json.load(f)

# IxP inputDefaults
ixp_id = ixp_def['inputDefaults']
ixp_model_blob = dict(ixp_def['inputDefaults']['model'])
# Fix: modelName is null, use modelDisplayName
if not ixp_model_blob.get('modelName'):
    ixp_model_blob['modelName'] = ixp_model_blob.get('modelDisplayName') or ixp_id.get('modelName')

# outputDefinition for IxP
ixp_out = ixp_def['outputDefinition']

# script outputDef
script_out = script_def['outputDefinition']

# Build the flow
flow = {
  'id': '34818ea3-ecbd-465f-a1e4-96dcb91c23b9',
  'version': '1.8',
  'name': 'ReceiptIntake',
  'nodes': [
    {
      'id': 'start',
      'type': 'core.trigger.manual',
      'typeVersion': '1.0',
      'display': {'label': 'Manual trigger'},
      'inputs': {
        'entryPointId': '2c94b6d8-d59f-4f26-8ee9-5c0ea3da34a7',
        'isDefaultEntryPoint': True
      }
    },
    {
      'id': 'extractReceipt',
      'type': ixp_def['nodeType'],
      'typeVersion': ixp_def.get('typeVersion', ixp_def.get('version','1.0.0')),
      'display': {'label': 'Extract Receipt Fields'},
      'inputs': {
        'model': ixp_model_blob,
        'modelName': ixp_id.get('modelName') or ixp_model_blob['modelName'],
        'projectName': ixp_id.get('projectName'),
        'folderKey': ixp_id.get('folderKey'),
        'folderName': ixp_id.get('folderName'),
        'versionTag': '',
        'pageRange': '',
        'fileRef': '=js:$vars.start.output.document'
      },
      'outputs': {
        'output': ixp_out['output'],
        'error': ixp_out['error']
      }
    },
    {
      'id': 'postReceipt',
      'type': 'core.action.script',
      'typeVersion': '1.0',
      'display': {'label': 'postReceipt'},
      'inputs': {
        'script': 'const result = $vars.extractReceipt.output;\nreturn { status: \"OK\", extractionResult: result };'
      },
      'outputs': {
        'output': {'type': 'object', 'description': 'The return value of the script', 'source': '=result.response', 'var': 'output'},
        'error': {'type': 'object', 'description': 'Error information if the node fails.', 'source': '=result.Error', 'var': 'error'}
      }
    },
    {
      'id': 'sendToValidation',
      'type': 'core.action.script',
      'typeVersion': '1.0',
      'display': {'label': 'sendToValidation'},
      'inputs': {
        'script': 'const result = $vars.extractReceipt.output;\nreturn { status: \"OK\", extractionResult: result };'
      },
      'outputs': {
        'output': {'type': 'object', 'description': 'The return value of the script', 'source': '=result.response', 'var': 'output'},
        'error': {'type': 'object', 'description': 'Error information if the node fails.', 'source': '=result.Error', 'var': 'error'}
      }
    },
    {
      'id': 'logError',
      'type': 'core.action.script',
      'typeVersion': '1.0',
      'display': {'label': 'logError'},
      'inputs': {
        'script': 'const errInfo = $vars.extractReceipt.error;\nreturn { status: \"OK\", errorInfo: errInfo };'
      },
      'outputs': {
        'output': {'type': 'object', 'description': 'The return value of the script', 'source': '=result.response', 'var': 'output'},
        'error': {'type': 'object', 'description': 'Error information if the node fails.', 'source': '=result.Error', 'var': 'error'}
      }
    },
    {
      'id': 'end',
      'type': 'core.control.end',
      'typeVersion': '1.0',
      'display': {'label': 'End'}
    }
  ],
  'edges': [
    {'id': 'e1', 'sourceNodeId': 'start', 'sourceHandle': 'output', 'targetNodeId': 'extractReceipt', 'targetPort': 'input'},
    {'id': 'e2', 'sourceNodeId': 'extractReceipt', 'sourceHandle': 'success', 'targetNodeId': 'postReceipt', 'targetPort': 'input'},
    {'id': 'e3', 'sourceNodeId': 'extractReceipt', 'sourceHandle': 'success', 'targetNodeId': 'sendToValidation', 'targetPort': 'input'},
    {'id': 'e4', 'sourceNodeId': 'extractReceipt', 'sourceHandle': 'error', 'targetNodeId': 'logError', 'targetPort': 'input'},
    {'id': 'e5', 'sourceNodeId': 'postReceipt', 'sourceHandle': 'success', 'targetNodeId': 'end', 'targetPort': 'input'},
    {'id': 'e6', 'sourceNodeId': 'sendToValidation', 'sourceHandle': 'success', 'targetNodeId': 'end', 'targetPort': 'input'},
    {'id': 'e7', 'sourceNodeId': 'logError', 'sourceHandle': 'success', 'targetNodeId': 'end', 'targetPort': 'input'}
  ],
  'definitions': [
    # manual trigger def already read from the flow
  ],
  'layout': {
    'nodes': {
      'start': {'position': {'x': 256, 'y': 144}},
      'extractReceipt': {'position': {'x': 0, 'y': 0}},
      'postReceipt': {'position': {'x': 0, 'y': 0}},
      'sendToValidation': {'position': {'x': 0, 'y': 0}},
      'logError': {'position': {'x': 0, 'y': 0}},
      'end': {'position': {'x': 0, 'y': 0}}
    }
  }
}

# Definitions: manual trigger (from original) + IxP + script + end
manual_trigger_def = {
  'nodeType': 'core.trigger.manual',
  'version': '1.0',
  'category': 'trigger',
  'description': 'Start workflow manually',
  'tags': ['trigger', 'start', 'manual'],
  'sortOrder': 40,
  'display': {'label': 'Manual trigger', 'icon': 'play', 'shape': 'circle'},
  'handleConfiguration': [{'position': 'right', 'handles': [{'id': 'output', 'type': 'source', 'handleType': 'output', 'showButton': True, 'constraints': {'forbiddenTargetCategories': ['trigger']}}], 'visible': True}],
  'model': {'type': 'bpmn:StartEvent', 'entryPointId': True},
  'outputDefinition': {'output': {'type': 'object', 'description': 'Data passed when manually triggering the workflow.', 'source': 'null', 'var': 'output'}},
  'toolbarExtensions': {'design': {'actions': [{'id': 'change-trigger-type', 'icon': 'square-mouse-pointer', 'label': 'Change trigger type'}]}}
}

flow['definitions'] = [manual_trigger_def, ixp_def, script_def, end_def]

print(json.dumps(flow, indent=2))
" > /tmp/receipt_flow.json 2>&1 && echo "JSON_BUILT" && wc -l /tmp/receipt_flow.json

